-- Only actual new message producers mint admissions. Legacy receives counters.
CREATE TABLE message_generation_origins (id TEXT PRIMARY KEY,message_id TEXT NOT NULL UNIQUE,session_id TEXT NOT NULL,tenant_id BIGINT NOT NULL,owner_id TEXT NOT NULL,owner_revision BIGINT NOT NULL,request_id TEXT NOT NULL,role TEXT NOT NULL,actor TEXT NOT NULL,initial_input TEXT NOT NULL);
CREATE TABLE message_material_admissions (id TEXT PRIMARY KEY,generation_id TEXT NOT NULL REFERENCES message_generation_origins(id),message_id TEXT NOT NULL,session_id TEXT NOT NULL,tenant_id BIGINT NOT NULL,owner_id TEXT NOT NULL,owner_revision BIGINT NOT NULL,revision BIGINT NOT NULL,body_digest TEXT NOT NULL,source_lineage TEXT NOT NULL,execution_context TEXT NOT NULL,agent_id TEXT NOT NULL,agent_tenant_id BIGINT NOT NULL);
CREATE TABLE message_material_receipts (message_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES message_material_admissions(id));
CREATE TABLE message_material_versions (message_id TEXT PRIMARY KEY,revision BIGINT NOT NULL CHECK(revision>0));
CREATE TABLE message_session_owner_versions (session_id TEXT PRIMARY KEY,revision BIGINT NOT NULL CHECK(revision>0));
CREATE TABLE message_session_membership_versions (session_id TEXT PRIMARY KEY,revision BIGINT NOT NULL CHECK(revision>0));
INSERT INTO message_material_versions SELECT id,1 FROM messages;
INSERT INTO message_session_owner_versions SELECT id,1 FROM sessions;
INSERT INTO message_session_membership_versions SELECT id,1 FROM sessions;
CREATE TRIGGER message_generation_origins_immutable_update BEFORE UPDATE ON message_generation_origins BEGIN SELECT RAISE(ABORT,'immutable original message producer'); END;
CREATE TRIGGER message_generation_origins_immutable_delete BEFORE DELETE ON message_generation_origins BEGIN SELECT RAISE(ABORT,'immutable original message producer'); END;
CREATE TRIGGER message_material_admissions_immutable_update BEFORE UPDATE ON message_material_admissions BEGIN SELECT RAISE(ABORT,'immutable original message producer'); END;
CREATE TRIGGER message_material_admissions_immutable_delete BEFORE DELETE ON message_material_admissions BEGIN SELECT RAISE(ABORT,'immutable original message producer'); END;
CREATE TRIGGER message_material_insert AFTER INSERT ON messages BEGIN INSERT INTO message_material_versions VALUES(NEW.id,1) ON CONFLICT(message_id) DO UPDATE SET revision=revision+1; INSERT INTO message_session_membership_versions VALUES(NEW.session_id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER message_material_update AFTER UPDATE ON messages WHEN (OLD.role='user' AND NEW.role='user' AND (OLD.session_id IS NOT NEW.session_id OR OLD.request_id IS NOT NEW.request_id OR OLD.role IS NOT NEW.role OR OLD.content IS NOT NEW.content OR OLD.is_completed IS NOT NEW.is_completed OR OLD.created_at IS NOT NEW.created_at OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.agent_id IS NOT NEW.agent_id OR OLD.agent_tenant_id IS NOT NEW.agent_tenant_id OR OLD.execution_context IS NOT NEW.execution_context)) OR ((OLD.role!='user' OR NEW.role!='user') AND (OLD.session_id IS NOT NEW.session_id OR OLD.request_id IS NOT NEW.request_id OR OLD.content IS NOT NEW.content OR OLD.role IS NOT NEW.role OR OLD.knowledge_references IS NOT NEW.knowledge_references OR OLD.source_lineage IS NOT NEW.source_lineage OR OLD.agent_steps IS NOT NEW.agent_steps OR OLD.mentioned_items IS NOT NEW.mentioned_items OR OLD.images IS NOT NEW.images OR OLD.attachments IS NOT NEW.attachments OR OLD.is_completed IS NOT NEW.is_completed OR OLD.is_fallback IS NOT NEW.is_fallback OR OLD.agent_duration_ms IS NOT NEW.agent_duration_ms OR OLD.usage IS NOT NEW.usage OR OLD.rendered_content IS NOT NEW.rendered_content OR OLD.channel IS NOT NEW.channel OR OLD.agent_id IS NOT NEW.agent_id OR OLD.agent_tenant_id IS NOT NEW.agent_tenant_id OR OLD.model_id IS NOT NEW.model_id OR OLD.execution_context IS NOT NEW.execution_context OR OLD.used_memories IS NOT NEW.used_memories OR OLD.sandbox_checkpoint IS NOT NEW.sandbox_checkpoint OR OLD.context_checkpoint IS NOT NEW.context_checkpoint OR OLD.created_at IS NOT NEW.created_at OR OLD.deleted_at IS NOT NEW.deleted_at)) BEGIN INSERT INTO message_material_versions VALUES(NEW.id,1) ON CONFLICT(message_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER message_material_membership_update AFTER UPDATE ON messages WHEN OLD.session_id IS NOT NEW.session_id OR OLD.created_at IS NOT NEW.created_at OR OLD.deleted_at IS NOT NEW.deleted_at BEGIN INSERT INTO message_session_membership_versions VALUES(OLD.session_id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; INSERT INTO message_session_membership_versions VALUES(NEW.session_id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER message_material_delete AFTER DELETE ON messages BEGIN INSERT INTO message_material_versions VALUES(OLD.id,1) ON CONFLICT(message_id) DO UPDATE SET revision=revision+1; INSERT INTO message_session_membership_versions VALUES(OLD.session_id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER message_session_owner_insert AFTER INSERT ON sessions BEGIN INSERT INTO message_session_owner_versions VALUES(NEW.id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; INSERT INTO message_session_membership_versions VALUES(NEW.id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER message_session_owner_update AFTER UPDATE ON sessions WHEN OLD.tenant_id IS NOT NEW.tenant_id OR OLD.user_id IS NOT NEW.user_id OR OLD.deleted_at IS NOT NEW.deleted_at BEGIN INSERT INTO message_session_owner_versions VALUES(NEW.id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER message_session_owner_delete AFTER DELETE ON sessions BEGIN INSERT INTO message_session_owner_versions VALUES(OLD.id,1) ON CONFLICT(session_id) DO UPDATE SET revision=revision+1; END;
